success.content:
.place-search-panel-root {
  position: fixed;
  inset: 0;
  z-index: 1200;
  pointer-events: none;
}

.place-search-panel__scrim {
  position: absolute;
  inset: 0;
  border: none;
  margin: 0;
  padding: 0;
  background: transparent;
  cursor: default;
  pointer-events: auto;
}

.place-search-panel {
  position: absolute;
  top: calc(var(--hud-pad-top, 0.65rem) + 2.55rem);
  left: var(--hud-pad-left, 0.65rem);
  width: min(18.5rem, calc(100vw - 1.3rem));
  max-height: min(14rem, 42vh);
  display: flex;
  flex-direction: column;
  border-radius: 12px;
  background: #FFFFFF;
  border: 1px solid #CBD5E1;
  box-shadow: var(--rtw-shadow-panel, 0 12px 32px rgba(0, 0, 0, 0.4));
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  color: #1F2937;
  pointer-events: auto;
  overflow: hidden;
}

.place-search-panel__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.45rem 0.55rem 0.35rem;
  border-bottom: 1px solid #E2E8F0;
}

.place-search-panel__title {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #1F2937;
}

.place-search-panel__close {
  flex-shrink: 0;
  width: 1.6rem;
  height: 1.6rem;
  border: none;
  border-radius: 8px;
  background: #F1F5F9;
  color: #475569;
  font-size: 1.1rem;
  line-height: 1;
  cursor: pointer;
}

.place-search-panel__close:hover {
  background: #EFF6FF;
  color: #1F2937;
}

.place-search-panel__body {
  overflow: auto;
}

.menu-place-search--panel {
  padding: 0.45rem 0.55rem 0.5rem;
  border-bottom: none;
  background: transparent;
}

.menu-place-search {
  padding: 0.45rem 0.55rem 0.4rem;
  border-bottom: 1px solid #E2E8F0;
  background: #F8FAFC;
  color: #1F2937;
  color-scheme: light;
}

.menu-place-search__label {
  display: block;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.72;
  margin-bottom: 0.28rem;
}

.menu-place-search__input-wrap {
  position: relative;
}

.menu-place-search__input {
  width: 100%;
  box-sizing: border-box;
  font: inherit;
  font-size: 0.84rem;
  padding: 0.38rem 0.5rem;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #FFFFFF;
  color: #1F2937;
}

.menu-place-search__input:focus {
  outline: 2px solid rgba(37, 99, 235, 0.45);
  outline-offset: 1px;
}

.menu-place-search__input:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.menu-place-search__hint {
  margin: 0.28rem 0 0;
  font-size: 0.72rem;
  opacity: 0.7;
  line-height: 1.3;
}

.menu-place-search__status {
  margin: 0.25rem 0 0;
  font-size: 0.72rem;
  opacity: 0.65;
}

.menu-place-search__list {
  list-style: none;
  margin: 0.28rem 0 0;
  padding: 0;
  max-height: 9rem;
  overflow: auto;
  border-radius: 8px;
  border: 1px solid #CBD5E1;
  background: #FFFFFF;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

.menu-place-search__item {
  display: block;
  width: 100%;
  text-align: left;
  font: inherit;
  font-size: 0.78rem;
  line-height: 1.3;
  padding: 0.38rem 0.5rem;
  border: none;
  border-bottom: 1px solid #E2E8F0;
  background: transparent;
  color: #1F2937;
  cursor: pointer;
}

.menu-place-search__item:last-child {
  border-bottom: none;
}

.menu-place-search__item:hover,
.menu-place-search__item:focus-visible {
  background: #EFF6FF;
}

.menu-place-search__item:focus-visible {
  outline: none;
}

